(6759762, 1011298, 109387, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Chinarosepetal:</b></div><hr/><i> Nice picture but I would call it background motion blur, not panning. :) </i></td></tr></table> <br/> <br/>Can you explain me the difference?</td>', 'Originally posted by Chinarosepetal: Nice picture but I would call it background motion blur, not panning. :)   Can you explain me the difference?', '2012-05-04 14:33:20.000000', NULL, 0),
(6759790, 1011298, 28359, '<td valign="top">Congrats on a awesome image &amp; the Blue. I was leaning more towards motion blur vs panning blur. Yet if the camera is spinning the camera is panning, so It meets the challenge right on for me..... Great Job!!!</td>', 'Congrats on a awesome image & the Blue. I was leaning more towards motion blur vs panning blur. Yet if the camera is spinning the camera is panning, so It meets the challenge right on for me..... Great Job!!!', '2012-05-04 15:21:00.000000', NULL, 0),
