(6760071, 1011486, 3724, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=753886" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg"/></a> <br/>speed of a soccer player, a crucial element of the game, individually developed by training &amp; experience - I enjoy this narrative expressing speed, but also the tucked-between the legs relationship to the player''s control of the ball. Enjoy this view.</td>', ' speed of a soccer player, a crucial element of the game, individually developed by training & experience - I enjoy this narrative expressing speed, but also the tucked-between the legs relationship to the player''s control of the ball. Enjoy this view.', '2012-05-05 00:47:04.000000', NULL, 0),
(6760076, 1011238, 3724, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=753886" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg"/></a> <br/> <br/>Undoubtedly subtle panning, but enough allowed to qualify - grain &amp; colour edit contribute to this marvelous view of a game I can never understand.</td>', '  Undoubtedly subtle panning, but enough allowed to qualify - grain & colour edit contribute to this marvelous view of a game I can never understand.', '2012-05-05 00:58:15.000000', NULL, 0),
